final Map<String, dynamic> _catalog = jsonDecode(_raw) as Map<String, dynamic>;
List<Map<String, dynamic>> get _departments => (_catalog['departments'] as List).cast<Map<String, dynamic>>();
List<Map<String, dynamic>> get _generic => (_catalog['generic'] as List).cast<Map<String, dynamic>>();

/// Lower-case, no Arabic diacritics, one spelling of alef / ya / ta marbuta, single spaces.
String normJob(String s) => s
    .toLowerCase()
    .replaceAll(RegExp('[\u064B-\u0652\u0640]'), '')
    .replaceAll(RegExp('[\u0623\u0625\u0622]'), '\u0627')
    .replaceAll('\u0649', '\u064A')
    .replaceAll('\u0629', '\u0647')
    .replaceAll(RegExp('[^a-z0-9\u0600-\u06FF ]+'), ' ')
    .replaceAll(RegExp(r'\s+'), ' ')
    .trim();

List<String> _tokens(String s) => normJob(s).split(' ').where((t) => t.isNotEmpty).toList();

/// The catalog department that best fits a typed department name (null = unknown, any name is allowed).
Map<String, dynamic>? matchDepartment(String name) {
  final n = normJob(name);
  if (n.length < 2) return null;
  final toks = _tokens(name).toSet();
  Map<String, dynamic>? best;
  var bestScore = 0;
  for (final d in _departments) {
    var score = 0;
    for (final cand in [d['en'] as String, d['ar'] as String, ...(d['aliases'] as List).cast<String>()]) {
      final c = normJob(cand);
      if (c.isEmpty) continue;
      if (c == n) {
        score = score < 100 ? 100 : score;
      } else if (c.length <= 3) {
        if (toks.contains(c) && score < 70) score = 70;
      } else if (n.contains(c)) {
        final s = 60 + (c.length < 30 ? c.length : 30);
        if (s > score) score = s;
      } else if (n.length >= 4 && c.contains(n)) {
        final s = 50 + (n.length < 20 ? n.length : 20);
        if (s > score) score = s;
      } else {
        final ct = _tokens(cand).where((t) => t.length > 3);
        if (ct.any(toks.contains) && score < 40) score = 40;
      }
    }
    if (score > bestScore) {
      bestScore = score;
      best = d;
    }
  }
  return bestScore >= 40 ? best : null;
}

/// Every department that can exist in a company, in the app language ('ar' or 'en').
List<Suggestion> departmentOptions(String lang) {
  final other = lang == 'ar' ? 'en' : 'ar';
  return [for (final d in _departments) Suggestion(d[lang] as String, d[other] as String)];
}

/// Titles for a department: its own catalog titles first, then titles already used in the company, then general ones.
List<Suggestion> titleOptions(String deptName, String lang, [List<String> existing = const []]) {
  final other = lang == 'ar' ? 'en' : 'ar';
  final out = <Suggestion>[];
  final seen = <String>{};
  void add(String label, [String alt = '']) {
    final k = normJob(label);
    if (k.isEmpty || !seen.add(k)) return;
    out.add(Suggestion(label, alt));
  }

  final d = matchDepartment(deptName);
  if (d != null) {
    for (final t in (d['titles'] as List).cast<Map<String, dynamic>>()) {
      add(t[lang] as String, t[other] as String);
    }
  }
  for (final t in existing) {
    add(t);
  }
  if (d != null) {
    for (final t in _generic) {
      add(t[lang] as String, t[other] as String);
    }
  } else {
    for (final t in _generic) {
      add(t[lang] as String, t[other] as String);
    }
    for (final x in _departments) {
      for (final t in (x['titles'] as List).cast<Map<String, dynamic>>()) {
        add(t[lang] as String, t[other] as String);
      }
    }
  }
  return out;
}

/// Is this title already in the list for that department (either language)? Used to ask before saving a brand-new title.
bool isKnownTitle(String value, String deptName, String lang, [List<String> existing = const []]) {
  final v = normJob(value);
  if (v.isEmpty) return true;
  final all = [...titleOptions(deptName, lang, existing), ...titleOptions(deptName, lang == 'ar' ? 'en' : 'ar')];
  for (final o in all) {
    if (normJob(o.label) == v || (o.alt.isNotEmpty && normJob(o.alt) == v)) return true;
  }
  for (final d in _departments) {
    for (final t in (d['titles'] as List).cast<Map<String, dynamic>>()) {
      if (normJob(t['en'] as String) == v || normJob(t['ar'] as String) == v) return true;
    }
  }
  for (final t in _generic) {
    if (normJob(t['en'] as String) == v || normJob(t['ar'] as String) == v) return true;
  }
  return false;
}
